mapper.select:
select count(0) from act_hi_actinst t
where end_time_ is not null
and end_time_ <= #{searchTimeEnd}
and end_time_ >= #{searchTimeBegin}
and assignee_ in

    #{userLoginName}

select count(0) from act_hi_procinst t
where start_time_ is not null
and start_time_ <= #{searchTimeEnd}
and start_time_ >= #{searchTimeBegin}
and start_user_id_ in

    #{userLoginName}

select name "name", count(0) as handle_cnt "handleCnt" from (
select


        to_char(end_time_, 'yyyy') as name


        to_char(end_time_, 'yyyy-MM') as name


from act_hi_actinst t
where end_time_ is not null
and end_time_ <= #{searchTimeEnd}
and end_time_ >= #{searchTimeBegin}
and assignee_ in

    #{userLoginName}

) temp group by name

select name "name", count(0) as create_cnt "createCnt" from (
select


        to_char(start_time_, 'yyyy') as name


        to_char(start_time_, 'yyyy-MM') as name


from act_hi_procinst t
where start_time_ is not null
and start_time_ <= #{searchTimeEnd}
and start_time_ >= #{searchTimeBegin}
and start_user_id_ in

    #{userLoginName}

) temp group by name

select re.key_ "modelKey", max(re.name_) "modelName", max(re.version_) "currentVersion", count(re.version_) "versionCnt", min(deploy.deploy_time_) "proCreateTime", max(deploy.deploy_time_) "lastCreateTime",
EXTRACT (DAY FROM sysdate - min(deploy.deploy_time_)) + 1 "proCreateDays"
TIMESTAMPDIFF(DAY,min(deploy.deploy_time_),now())+1 "proCreateDays"
from act_re_procdef re left join act_re_deployment deploy on re.deployment_id_ = deploy.id_
AND re.category_ = #{classifyId}
AND re.name_ like #{modelNameLike}
AND re.tenant_id_ = #{tenantId}
group by re.key_
